ALTER TABLE public.profiles ADD COLUMN material_event_email_enabled boolean NOT NULL DEFAULT false;
CREATE TABLE public.earnings_calls (ticker text NOT NULL, quarter text NOT NULL, data jsonb, status text NOT NULL DEFAULT 'processing', error text, lease_until timestamptz, PRIMARY KEY(ticker,quarter)); GRANT ALL ON public.earnings_calls TO service_role; ALTER TABLE public.earnings_calls ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.material_events (accession text PRIMARY KEY REFERENCES public.filings(accession), ticker text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.material_events TO service_role; ALTER TABLE public.material_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.event_deliveries (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, accession text NOT NULL REFERENCES public.filings(accession), recipient text NOT NULL, status text NOT NULL CHECK(status IN ('sending','sent','uncertain')), gmail_id text, error text, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,accession)); GRANT SELECT ON public.event_deliveries TO authenticated; GRANT ALL ON public.event_deliveries TO service_role; ALTER TABLE public.event_deliveries ENABLE ROW LEVEL SECURITY; CREATE POLICY "Owners read event delivery history" ON public.event_deliveries FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE TABLE public.event_monitor (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, enabled_since timestamptz NOT NULL DEFAULT now(), cursor integer NOT NULL DEFAULT 0, lease_until timestamptz, paused_reason text, last_checked_at timestamptz); GRANT SELECT ON public.event_monitor TO authenticated; GRANT ALL ON public.event_monitor TO service_role; ALTER TABLE public.event_monitor ENABLE ROW LEVEL SECURITY; CREATE POLICY "Owners read event monitor status" ON public.event_monitor FOR SELECT TO authenticated USING(auth.uid()=user_id);